pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 preBalance, uint256 unlockTime) public {
        // admissible domain: very wide, only constrain to avoid overflow in vm.deal and to keep msg.value non-zero
        amount = bound(amount, 1, type(uint128).max);
        preBalance = bound(preBalance, 0, type(uint128).max);
        unlockTime = bound(unlockTime, block.timestamp + 1, type(uint64).max);
        address actor = address(uint160(uint256(keccak256(abi.encode(amount, preBalance, unlockTime)))));
        vm.assume(actor != address(0) && actor != address(this));

        // set up pre-balance via a prior Put (using a separate msg.sender to avoid collision if actor same as pre-actor)
        // But we need actor to have a known balance before the tested Put.
        // We'll give actor some balance via a Put with a different msg.value. We control actor completely.
        vm.deal(actor, preBalance + amount + 1 ether); // enough for preBalance deposit and the actual Put
        vm.prank(actor);
        c.Put{value: preBalance}(unlockTime);

        // record balance before the tested Put
        (uint256 unlockBefore, uint256 balBefore) = c.Acc(actor);

        // prepare the amount that, when added to balBefore, overflows if the check is removed.
        // In reference, solidity 0.8.0 has built-in overflow checks in unchecked? No, it's checked by default.
        // But the require guards against overflow when balBefore + amount < balBefore modulo 2^256.
        // To trigger overflow: amount = type(uint256).max - balBefore + 1 (but bound may restrict).
        // Instead let fuzzer pick amount freely; reference will revert on overflow because require(balBefore+amount >= balBefore) fails,
        // but buggy will not revert and will wrap around.
        // We set up actor with enough ether for this Put.
        vm.deal(actor, amount);
        bool ok = true;
        vm.prank(actor);
        try c.Put{value: amount}(unlockTime) {
        } catch {
            ok = false;
        }

        // After the call, read the actual balance.
        (, uint256 balAfter) = c.Acc(actor);

        // The invariant: if the Put succeeded, the new balance must be exactly balBefore + amount (no overflow wrap).
        // Equivalently, balAfter >= balBefore.
        // The buggy version may succeed with overflow, resulting in balAfter < balBefore.
        // We also need to consider that reference may revert, then no state change -> ok==false, but the check fails? 
        // The property after a successful Put (ok==true) is balAfter >= balBefore.
        // If reference always reverts on overflow, then ok will be false for those inputs and property is vacuously true (ok -> balAfter >= balBefore).
        // Bug will succeed and balAfter < balBefore, making ok true but property false.
        assertTrue(!ok || balAfter >= balBefore);
    }
}

