pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 sentValue, uint256 preBalance, uint256 unlockTime) public {
        // Bound sentValue and preBalance so their sum does not overflow uint256
        bound(sentValue, 0, type(uint256).max - preBalance);
        address actor = address(0x1234);
        vm.deal(actor, sentValue);
        // Set the initial balance of the actor
        // We need a way to set the balance; we can use Put with a zero value to create the account, but we need to set balance directly.
        // Since Acc is public and has a getter, we can't set it directly. We'll use Put with msg.value = preBalance first.
        // But we need to set balance without triggering the overflow check in the reference. We'll use two calls: first with preBalance as value, then test the second call.
        // However, we must respect the rule that we only interact through c's public surface. We'll make an initial Put to establish the preBalance.
        // To avoid dealing with unlockTime constraints, we just warp to the far future.
        vm.warp(1);
        vm.prank(actor);
        c.Put{value: preBalance}(unlockTime);
        // Now the actor's balance is preBalance. Record it.
        uint256 balanceBefore = c.Acc(actor).balance;
        // Now send the sentValue
        vm.prank(actor);
        c.Put{value: sentValue}(unlockTime);
        uint256 balanceAfter = c.Acc(actor).balance;
        // The rule: balanceAfter must equal balanceBefore + sentValue
        assertTrue(balanceAfter == balanceBefore + sentValue);
    }
}

