import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 collectAmount) public {
        // Bound collectAmount to something reasonable; keep wide.
        collectAmount = bound(collectAmount, 1 ether, 1000 ether);
        // For reproducibility, restrict unlockTime close to current block timestamp.
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 365 days);
        address actor = address(0x1234);
        uint256 deposit = collectAmount;
        vm.deal(actor, deposit);
        // Deposit to create an account with balance >= MinSum and set unlockTime.
        vm.prank(actor);
        c.Put{value: deposit}(unlockTime);
        // Warp exactly to unlockTime so block.timestamp == unlockTime.
        vm.warp(unlockTime);
        // By design, unlockTime is >= block.timestamp (it was set in the past or now).
        // Now try to Collect.
        vm.prank(actor);
        bool ok;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }
        // Reference: collect must revert when block.timestamp == unlockTime (strict >).
        // Mutant: collect succeeds (>=). Therefore after the call, the reference balance
        // must equal the deposit (unchanged), whereas the mutant balance would be zero.
        assertTrue(c.Acc(actor).balance == deposit);
    }
}

